const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={play:'<path d="m9 5 11 7-11 7Z"/>',pause:'<path d="M8 5v14M16 5v14"/>',next:'<path d="m5 5 10 7-10 7ZM19 5v14"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',send:'<path d="m3 10 18-7-7 18-4-7-7-4Zm7 4L21 3"/>'};
const icon=k=>'<svg viewBox="0 0 24 24" aria-hidden="true">'+icons[k]+'</svg>';
export function createRadio({cloud,context,modal,records}){
 let data={configured:false,hearts:[],gifts:[]},tracks=[],current=null,mode='discover',queue=[],error='',loading=false,saving=false,requestId=0,playId=0;
 const audio=new Audio();audio.preload='none';audio.volume=.65;audio.setAttribute('data-echoo-radio','');document.body.append(audio);
 const mini=document.createElement('div');mini.className='fm-mini';mini.hidden=true;document.body.append(mini);
 const active=()=>context().panel==='radio';
 const btn=(action,label,glyph,cls='')=>'<button type="button" data-fm="'+action+'" aria-label="'+label+'" title="'+label+'" class="fm-icon '+cls+'">'+icon(glyph)+'</button>';
 function message(text){error=text;const el=document.querySelector('[data-fm-status]');if(el)el.textContent=text;mini.title=text;}
 function paint(){
  const liked=current&&data.hearts.includes(current.id);
  document.querySelectorAll('[data-fm=toggle]').forEach(b=>{b.innerHTML=icon(audio.paused?'play':'pause');b.setAttribute('aria-label',audio.paused?'播放':'暂停');b.title=audio.paused?'播放':'暂停';b.disabled=loading||!current});
  document.querySelectorAll('[data-fm=heart]').forEach(b=>{b.classList.toggle('is-liked',!!liked);b.setAttribute('aria-pressed',String(!!liked));b.setAttribute('aria-label',liked?'取消红心':'红心收藏');b.disabled=saving||!current});
  const nextButton=document.querySelector('[data-fm=next]');if(nextButton)nextButton.disabled=loading||!tracks.length;
  const seek=document.querySelector('[data-fm-seek]');if(seek){seek.max=Number.isFinite(audio.duration)?audio.duration:current?.duration||0;seek.value=audio.currentTime||0;seek.disabled=!Number.isFinite(audio.duration);}
  const time=n=>Math.floor(n/60)+':'+String(Math.floor(n%60)).padStart(2,'0');const counter=document.querySelector('[data-fm-time]');if(counter)counter.textContent=time(audio.currentTime||0)+' / '+time(Number.isFinite(audio.duration)?audio.duration:current?.duration||0);
  mini.hidden=!current;mini.classList.toggle('is-playing',!audio.paused);
  if(current)mini.innerHTML='<button data-fm="open" class="fm-mini-title"><span>♫</span><span>'+esc(current.title)+'<small>阿球 FM</small></span></button>'+btn('toggle',audio.paused?'播放':'暂停',audio.paused?'play':'pause');
 }
 function render(){
  const t=current;
  modal('radio','A LITTLE MUSIC, JUST FOR YOU','阿球 FM',`<section class="echoo-fm"><div class="fm-tabs" role="group" aria-label="选择音乐频道">${[['discover','随心听'],['hearts','我的红心'],['gifts','你留的歌']].map(([id,label])=>'<button data-fm="channel" data-mode="'+id+'" class="'+(mode===id?'selected':'')+'" aria-pressed="'+(mode===id)+'">'+label+'</button>').join('')}</div><div class="fm-art"><span class="fm-art-empty">♫<small>${loading?'正在寻找一首歌':'等一首歌，落在这里'}</small></span>${t?.cover?'<img src="'+esc(t.cover)+'" alt="'+esc(t.title)+'的专辑封面" referrerpolicy="no-referrer">':''}</div><h3 class="fm-song">${esc(t?.title||'和喜欢的音乐，不期而遇')}</h3><p class="fm-artist">${esc(t?.artist||'为日常留一点旋律')}</p><div class="fm-timeline"><input type="range" min="0" max="0" value="0" step="1" aria-label="播放进度" data-fm-seek disabled><small data-fm-time>0:00 / 0:00</small></div><div class="fm-controls">${btn('heart','红心收藏','heart')+btn('toggle','播放','play','fm-play')+btn('next','下一首','next')+btn('gift','留给对方','send')}</div><p class="fm-status" data-fm-status role="status" aria-live="polite">${esc(error)}</p>${mode==='gifts'?'<div class="fm-gifts">'+data.gifts.filter(g=>g.track===t?.id).map(g=>'<blockquote>'+esc(g.message||'这首歌，想让你也听见。')+'</blockquote>').join('')+'</div>':''}<div class="fm-credit">${t?'<a href="'+esc(t.url)+'" target="_blank" rel="noopener noreferrer">'+esc(t.artist)+' · Jamendo ↗</a>'+(t.license?' · <a href="'+esc(t.license)+'" target="_blank" rel="noopener noreferrer">歌曲许可</a>':''):'音乐来源 · Jamendo'}</div><div class="fm-footer"><button data-fm="reload">${loading?'加载中…':'重新加载'}</button><button data-fm="records">留歌唱片架</button>${data.canConfigure?'<button data-fm="settings">音乐设置</button>':''}</div></section>`);
  const image=document.querySelector('.fm-art img');if(image)image.onerror=()=>{image.remove();const label=document.querySelector('.fm-art-empty small');if(label)label.textContent='封面暂未载入'};
  document.querySelector('[data-fm=next]').disabled=loading||!tracks.length;document.querySelector('[data-fm=gift]').disabled=saving||!current;
  paint();
 }
 async function load(){const id=++requestId;loading=true;error='';if(active())render();
  try{if(!cloud)throw Error('阿球 FM 需要登录云端版。');const r=await cloud.radioView(mode);if(id!==requestId)return;data=r;tracks=r.tracks;queue=[];if(!r.configured)error=r.canConfigure?'还没有连接音乐来源，请点下方「音乐设置」。':'音乐来源尚未配置，请让第一位住户完成音乐设置。';else if(!tracks.length)error=mode==='hearts'?'点一颗红心，把喜欢的歌留在这里。':mode==='gifts'?'这里等着对方留给你的一首歌。':'暂时没有找到歌曲，请重试。';
  }catch(e){if(id!==requestId)return;error=e.message||'歌曲暂时没有加载成功。'}finally{if(id===requestId){loading=false;if(!current&&tracks.length)current=tracks[Math.floor(Math.random()*tracks.length)];if(active())render()}}
 }
 async function play(t){if(!t||!cloud)return;const token=++playId;audio.pause();audio.removeAttribute('src');audio.load();current=t;loading=true;message('正在连接这首歌…');if(active())render();
  try{const r=await cloud.radioTrack(t.id);if(token!==playId)return;current=r.track;audio.src=r.track.audio;audio.load();loading=false;if(active())render();try{await audio.play();message('')}catch{message('点一下播放，开始听这首歌。')}}catch(e){if(token===playId){loading=false;message(e.message||'这首歌暂时无法播放，试试下一首。')}}finally{if(token===playId)paint()}
 }
 function shuffled(list){const a=[...list];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a;}
 async function next(){if(loading)return;if(!tracks.length){await load();if(!tracks.length)return}if(!queue.length)queue=shuffled(tracks.filter(t=>t.id!==current?.id));const t=queue.shift()||tracks[0];return play(t)}
 async function toggle(){if(!current)return;if(!audio.paused){audio.pause();return}if(!audio.src)return play(current);try{await audio.play();message('')}catch{message('浏览器未能开始播放，请再点一次，或试试下一首。')}}
 async function mutate(payload){if(saving)return null;saving=true;paint();try{const r=await cloud.radio(payload);if(!r)throw Error(cloud.lastActionError||'暂时没有保存成功');data={...data,...r};return r}catch(e){message(e.message);return null}finally{saving=false;paint()}}
 function settings(){modal('radio-settings','CONNECT YOUR MUSIC','连接阿球 FM',`<p class="subtle">只需第一位住户设置一次，两个人就能听。这里填写应用的 Client ID，不是音乐账号密码。</p><ol class="fm-steps"><li>打开 <a href="https://devportal.jamendo.com/" target="_blank" rel="noopener noreferrer">Jamendo 开发者网站 ↗</a>，注册并登录。</li><li>创建一个应用，名称填 Echoo，网址填阿球的网址，说明用于两个人的非商业音乐播放器。</li><li>选择只读（Read only）接口，复制应用的 Client ID，粘贴到下面。</li></ol><form id="fm-config"><label>Client ID<input name="clientId" autocomplete="off" required maxlength="128" placeholder="粘贴应用的 Client ID"></label><p class="subtle">不需要 Client Secret，也不需要复制账户密码。</p><button class="pill primary" type="submit">验证并连接音乐</button><p role="status" data-fm-config-status></p></form><button class="pill" data-fm="open">返回播放器</button>`)}
 function gift(){if(!current)return;if(!cloud.paired){message('先在「账号与配对」连接对方，再把这首歌留给 TA。');return}const t=current;modal('radio-gift','THIS SONG MADE ME THINK OF YOU','把这首歌，留给你',`<p>《${esc(t.title)}》 · ${esc(t.artist)}</p><form id="fm-gift" data-track="${t.id}"><label>想说的话<textarea name="message" maxlength="500" placeholder="听到这首歌的时候，想起了你。"></textarea></label><button class="pill primary" type="submit">留给对方</button><p role="status" data-fm-gift-status></p></form><button class="pill" data-fm="open">返回播放器</button>`)}
 async function click(e){const b=e.target.closest('[data-fm]');if(!b||b.disabled)return;switch(b.dataset.fm){case'open':return open();case'toggle':return toggle();case'next':return next();case'channel':if(loading)return;mode=b.dataset.mode;audio.pause();audio.removeAttribute('src');audio.load();++playId;current=null;tracks=[];return load();case'reload':if(!loading)return load();return;case'heart':if(current){const liked=!data.hearts.includes(current.id);if(await mutate({action:'heart',id:current.id,liked})){if(mode==='hearts'&&!liked){tracks=tracks.filter(t=>t.id!==current.id);queue=queue.filter(t=>t.id!==current.id)}message(liked?'已收进自己的红心。':'已取消红心。')}}return;case'gift':return gift();case'settings':return settings();case'records':return records();}}
 document.querySelector('#panel-body').addEventListener('click',click);mini.addEventListener('click',click);
 document.querySelector('#panel-body').addEventListener('input',e=>{if(e.target.matches('[data-fm-seek]')&&Number.isFinite(audio.duration))audio.currentTime=Number(e.target.value)});
 document.querySelector('#panel-body').addEventListener('submit',async e=>{const f=e.target;if(!['fm-config','fm-gift'].includes(f.id))return;e.preventDefault();const b=f.querySelector('button[type=submit]'),out=f.querySelector('[role=status]');if(b.disabled)return;b.disabled=true;out.textContent='正在保存…';try{const d=Object.fromEntries(new FormData(f));const r=await mutate(f.id==='fm-config'?{action:'configure',clientId:d.clientId.trim()}:{action:'gift',id:f.dataset.track,message:d.message});if(!r){out.textContent=error;return}if(f.id==='fm-config'){await open();}else{f.reset();out.textContent='已经留给对方，也写进共同手账了。';}}finally{b.disabled=false}});
 audio.addEventListener('play',paint);audio.addEventListener('pause',paint);audio.addEventListener('timeupdate',paint);audio.addEventListener('loadedmetadata',paint);audio.addEventListener('ended',next);audio.addEventListener('error',()=>{if(audio.getAttribute('src'))message('音源暂时无法播放，收藏仍保留，可以重试或换下一首。');paint()});
 document.addEventListener('click',e=>{if(e.target.closest('[data-do=logout]')){++playId;audio.pause();audio.removeAttribute('src');current=null;paint()}});
 async function open(){render();await load()}
 return {open};
}
